import 'server-only';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { Readable } from 'node:stream';
import { r2Origin } from '@/lib/storage-origin';
import { env } from '../env';

/**
 * Where uploaded files live: Cloudflare R2 in production, a local folder in development.
 * Keys are always generated by BluePrint (never taken from a user's file name).
 */
export interface Storage {
  kind: 'local' | 'r2';
  put(key: string, body: Uint8Array, contentType: string): Promise<void>;
  size(key: string): Promise<number | null>;
  /** Reads up to `length` bytes from the start of the object (for checking the real file type). */
  readStart(key: string, length: number): Promise<Uint8Array>;
  stream(key: string): Promise<ReadableStream<Uint8Array> | null>;
  delete(key: string): Promise<void>;
  /** A short-lived URL the browser can upload to directly (R2 only). */
  presignPut?(key: string, contentType: string, expiresSeconds: number): Promise<string>;
  /** A short-lived download URL on the storage domain (R2 only). */
  presignGet?(key: string, opts: { filename: string; contentType: string; inline: boolean; expiresSeconds: number }): Promise<string>;
}

const KEY_PATTERN = /^[a-z0-9][a-z0-9/_-]{0,200}$/;

export function assertSafeKey(key: string) {
  if (!KEY_PATTERN.test(key) || key.includes('..') || key.includes('//')) throw new Error('Unsafe storage key');
}

/** `Content-Disposition` value that survives any file name (RFC 6266 / 5987). */
export function contentDisposition(filename: string, inline: boolean) {
  const clean = filename.replace(/[\r\n"\\]/g, '_').slice(0, 180) || 'file';
  const ascii = clean.replace(/[^\x20-\x7e]/g, '_');
  return `${inline ? 'inline' : 'attachment'}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(clean)}`;
}

class LocalStorage implements Storage {
  kind = 'local' as const;
  private base = path.resolve(env().LOCAL_STORAGE_DIR);

  private file(key: string) {
    assertSafeKey(key);
    const full = path.resolve(this.base, key);
    if (!full.startsWith(this.base + path.sep)) throw new Error('Unsafe storage key');
    return full;
  }

  async put(key: string, body: Uint8Array) {
    const full = this.file(key);
    await fsp.mkdir(path.dirname(full), { recursive: true });
    await fsp.writeFile(full, body, { mode: 0o600 });
  }

  async size(key: string) {
    try {
      return (await fsp.stat(this.file(key))).size;
    } catch {
      return null;
    }
  }

  async readStart(key: string, length: number) {
    const fh = await fsp.open(this.file(key), 'r');
    try {
      const buf = Buffer.alloc(length);
      const { bytesRead } = await fh.read(buf, 0, length, 0);
      return new Uint8Array(buf.subarray(0, bytesRead));
    } finally {
      await fh.close();
    }
  }

  async stream(key: string) {
    const full = this.file(key);
    if (!fs.existsSync(full)) return null;
    return Readable.toWeb(fs.createReadStream(full)) as ReadableStream<Uint8Array>;
  }

  async delete(key: string) {
    await fsp.rm(this.file(key), { force: true });
  }
}

class R2Storage implements Storage {
  kind = 'r2' as const;
  private clientPromise: Promise<import('@aws-sdk/client-s3').S3Client> | null = null;
  private bucket = env().R2_BUCKET!;

  private async client() {
    if (!this.clientPromise) {
      this.clientPromise = import('@aws-sdk/client-s3').then(({ S3Client }) => {
        const e = env();
        const endpoint = r2Origin(e.R2_ACCOUNT_ID, e.R2_JURISDICTION);
        if (!endpoint) throw new Error('R2_ACCOUNT_ID (and R2_JURISDICTION, if set) are not valid');
        return new S3Client({
          region: 'auto',
          endpoint,
          credentials: { accessKeyId: e.R2_ACCESS_KEY_ID!, secretAccessKey: e.R2_SECRET_ACCESS_KEY! },
        });
      });
    }
    return this.clientPromise;
  }

  async put(key: string, body: Uint8Array, contentType: string) {
    assertSafeKey(key);
    const { PutObjectCommand } = await import('@aws-sdk/client-s3');
    await (await this.client()).send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: body, ContentType: contentType }));
  }

  async size(key: string) {
    assertSafeKey(key);
    const { HeadObjectCommand } = await import('@aws-sdk/client-s3');
    try {
      const r = await (await this.client()).send(new HeadObjectCommand({ Bucket: this.bucket, Key: key }));
      return r.ContentLength ?? 0;
    } catch {
      return null;
    }
  }

  async readStart(key: string, length: number) {
    assertSafeKey(key);
    const { GetObjectCommand } = await import('@aws-sdk/client-s3');
    const r = await (await this.client()).send(new GetObjectCommand({ Bucket: this.bucket, Key: key, Range: `bytes=0-${length - 1}` }));
    return r.Body ? await r.Body.transformToByteArray() : new Uint8Array();
  }

  async stream(key: string) {
    assertSafeKey(key);
    const { GetObjectCommand } = await import('@aws-sdk/client-s3');
    try {
      const r = await (await this.client()).send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
      return r.Body ? (r.Body.transformToWebStream() as ReadableStream<Uint8Array>) : null;
    } catch {
      return null;
    }
  }

  async delete(key: string) {
    assertSafeKey(key);
    const { DeleteObjectCommand } = await import('@aws-sdk/client-s3');
    await (await this.client()).send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }

  async presignPut(key: string, contentType: string, expiresSeconds: number) {
    assertSafeKey(key);
    const [{ PutObjectCommand }, { getSignedUrl }] = await Promise.all([import('@aws-sdk/client-s3'), import('@aws-sdk/s3-request-presigner')]);
    return getSignedUrl(await this.client(), new PutObjectCommand({ Bucket: this.bucket, Key: key, ContentType: contentType }), { expiresIn: expiresSeconds });
  }

  async presignGet(key: string, opts: { filename: string; contentType: string; inline: boolean; expiresSeconds: number }) {
    assertSafeKey(key);
    const [{ GetObjectCommand }, { getSignedUrl }] = await Promise.all([import('@aws-sdk/client-s3'), import('@aws-sdk/s3-request-presigner')]);
    return getSignedUrl(
      await this.client(),
      new GetObjectCommand({
        Bucket: this.bucket,
        Key: key,
        ResponseContentType: opts.contentType,
        ResponseContentDisposition: contentDisposition(opts.filename, opts.inline),
      }),
      { expiresIn: opts.expiresSeconds },
    );
  }
}

let instance: Storage | null = null;
let override: Storage | null = null;

export function storage(): Storage {
  if (override) return override;
  if (!instance) instance = env().STORAGE_PROVIDER === 'r2' ? new R2Storage() : new LocalStorage();
  return instance;
}

/** Tests can swap in an in-memory store. */
export function setStorageForTests(s: Storage | null) {
  override = s;
}

/** A simple in-memory store, used by tests. */
export class MemoryStorage implements Storage {
  kind = 'local' as const;
  objects = new Map<string, Uint8Array>();
  async put(key: string, body: Uint8Array) {
    assertSafeKey(key);
    this.objects.set(key, body);
  }
  async size(key: string) {
    return this.objects.get(key)?.byteLength ?? null;
  }
  async readStart(key: string, length: number) {
    return (this.objects.get(key) ?? new Uint8Array()).subarray(0, length);
  }
  async stream(key: string) {
    const body = this.objects.get(key);
    if (!body) return null;
    return new ReadableStream<Uint8Array>({
      start(c) {
        c.enqueue(body);
        c.close();
      },
    });
  }
  async delete(key: string) {
    this.objects.delete(key);
  }
}
